execution.command:
RUN_ID="${LONGCOT_MINI_RUN_ID:-longcot_mini_re4_$(date -u +%Y%m%dT%H%M%SZ)}"; OUT_DIR="data/longcot_mini_calibration/${RUN_ID}"; mkdir -p "${OUT_DIR}"; .venv/bin/python scripts/benchmark/run_benchmark.py --suite longcot_mini --model frontdoor --server-mode --skip-speed-tests --skip-preflight --baseline-run "${RUN_ID}" --force && .venv/bin/python scripts/benchmark/run_benchmark.py --suite longcot_mini --model worker_general --server-mode --skip-speed-tests --skip-preflight --baseline-run "${RUN_ID}" --force && for result in benchmarks/results/runs/"${RUN_ID}"/frontdoor_*.json benchmarks/results/runs/"${RUN_ID}"/worker_general_*.json; do
  test -f "${result}" || { echo "missing LongCoT-Mini result files for ${RUN_ID}" >&2; exit 2; };
  stem="$(basename "${result}" .json)";
  .venv/bin/python scripts/benchmark/score_longcot_run.py "${result}"
  --output "${OUT_DIR}/${stem}_score.json";
done
